"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["58336"],{20587(e){e.exports=JSON.parse('{"id":11494,"title":"DRAA SWEET","description":"\\"Cinematic vertical video for Instagram Reel, 9:16 ratio. Opening shot: a breathtaking golden hour sunrise over the lush green palm groves and golden sand dunes of the Draa Valley in Morocco. Seamless transition to a macro, slow-motion shot of thick, rich, glossy dark amber date syrup pouring smoothly from a golden spoon into an elegant glass jar. Fresh, plump Medjool dates and a small traditional bowl are beautifully arranged on a rustic desert stone table. Warm, inviting sunlight glowing from the background. High-end food commercial style, highly detailed, photorealistic, 4k resolution","remark":"I want to create a promotional video for a product DRAA SWEET ","notes":"Le Sirop de Dattes Draa Sweet est un nectar premium et authentique, v\xe9ritable concentr\xe9 de nature issu directement des c\xe9l\xe8bres palmeraies de la Vall\xe9e du Dr\xe2a, au sud-est du Maroc. Pr\xe9sent\xe9 dans un \xe9l\xe9gant bocal en verre transparent, il met en valeur la richesse et la puret\xe9 de ce tr\xe9sor du d\xe9sert.\\n\\n\u2728 Caract\xe9ristiques Principales (Visibles sur l\'\xe9tiquette)\\nPoids net : 250g.\\n\\n100% Naturel : Un produit brut, extrait exclusivement de dattes de haute qualit\xe9.\\n\\nSans Sucre Ajout\xe9 : Sa douceur intense et gourmande provient uniquement du sucre naturel des fruits (fructose). Id\xe9al pour une alimentation saine.\\n\\nSans Additifs & Sans Conservateurs : Une composition totalement saine et transparente, sans produits chimiques, garantissant le go\xfbt originel du fruit.\\n\\nOrigine Certifi\xe9e : \\"Vall\xe9e du Dr\xe2a\\", un terroir mondialement reconnu pour l\'excellence de ses dattes.\\n\\n\u{1F36F} Profil Sensoriel\\nAspect Visuel : Le sirop pr\xe9sente une magnifique texture \xe9paisse, onctueuse et brillante. Sa couleur est d\'un ambre tr\xe8s sombre, presque brun profond, rappelant la richesse du caramel ou du miel de for\xeat.\\n\\nGo\xfbt et Ar\xf4me (d\xe9duit du produit) : Une saveur riche, suave et naturellement sucr\xe9e, avec des notes chaudes et caram\xe9lis\xe9es caract\xe9ristiques des dattes gorg\xe9es de soleil.\\n\\n\u{1F3A8} Design et Packaging\\nLe bocal est ferm\xe9 par un couvercle dor\xe9 \xe9l\xe9gant qui souligne le c\xf4t\xe9 \\"produit de qualit\xe9 premium\\". L\'\xe9tiquette invite au voyage : avec ses tons beiges textur\xe9s fa\xe7on parchemin ancien, elle illustre un paysage idyllique du d\xe9sert marocain (des dromadaires traversant les dunes de sable sous un soleil \xe9clatant, encadr\xe9s par des palmiers). La typographie est \xe0 la fois classique et raffin\xe9e, inspirant la tradition et l\'authenticit\xe9.","owner":"k.ouaakka@edu.umi.ac.ma","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-04-13T20:39:05.649Z"}')}}]);